<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}
mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);
require_once __DIR__.'/../backend/db.php';
require_once __DIR__.'/../backend/student_assessment_helper_lms.php';
require_once __DIR__.'/../backend/assessment_followup_helper_lms.php';
require_once __DIR__.'/../backend/professor_class_helper_lms.php';
require_once __DIR__.'/fixtures/professor-workload-students-data.php';
$lms=synk_database_connection_lms($conn);$checks=0;
$check=static function(bool $ok,string $message)use(&$checks):void{if(!$ok)throw new RuntimeException($message);$checks++;};
$denied=static function(callable $fn,int $code)use($check):void{try{$fn();$check(false,'An unauthorized report succeeded.');}catch(DomainException $error){$check($error->getCode()===$code,$error->getMessage());}};
$coreTables='tbl_useraccount,tbl_useraccount_roles,tbl_useraccount_faculty_links,tbl_faculty,tbl_class_schedule,tbl_faculty_workload_sched,tbl_academic_settings,tbl_student_management,tbl_student_management_enrolled_subjects,tbl_offering_enrollee_counts,'.synk_schedule_merge_table_name();
$lmsTables='tbl_lms_assessments,tbl_lms_assessment_questions,tbl_lms_assessment_logs,tbl_lms_assessment_attempts';
$coreBefore=$conn->query('CHECKSUM TABLE '.$coreTables)->fetch_all(MYSQLI_ASSOC);$lmsBefore=$lms->query('CHECKSUM TABLE '.$lmsTables)->fetch_all(MYSQLI_ASSOC);
$conn->begin_transaction();$lms->begin_transaction();
try {
    $f=professor_students_fixtures($conn,true);$sid=$f['students']['active'];$second=$f['students']['inactive'];$third=$f['students']['failed'];$actor=$f['user_id'];
    $classes=array_column(synk_professor_fetch_subject_rows_by_academic_year($conn,$f['faculty_id'],(int)$f['term']['ay_id'],(int)$f['term']['semester']),null,'offering_id');
    $context=['portal'=>['faculty_id'=>$f['faculty_id']],'class'=>$classes[$f['offerings'][0]['offering_id']]];
    $sample=['grading_period'=>'final','assessment_type'=>'exam','title'=>"Quiz <script>literal</script>\nSecond line",'time_limit_minutes'=>20,'due_at'=>'2099-01-01T17:00','questions'=>[['question_type'=>'true_false','prompt'=>'True statement','points'=>1,'answer_key'=>true]]];
    $draft=synk_assessment_save_lms($lms,$context,$sample,$actor);
    $denied(static function()use($conn,$lms,$context,$draft){synk_assessment_missing_submissions_lms($conn,$lms,$context,$draft['assessment_id']);},409);
    $a=synk_assessment_publish_lms($lms,$context,$sample,$actor);$id=$a['assessment_id'];
    $report=synk_assessment_missing_submissions_lms($conn,$lms,$context,$id);
    $check($report['counts']===['students'=>3,'submitted'=>0,'missing'=>3],'Use actual deduplicated enrollment, including legacy matching, instead of the recorded headcount of 260.');
    $check(count($report['students'])===3&&count(array_unique(array_column($report['students'],'student_number')))===3,'Each enrolled student appears once.');
    $check($report['students'][0]['student_name']==='Student, Ana Test Jr.','Names are complete and sorted by surname and given name.');
    $conn->query('SAVEPOINT followup_merge');$mergeTable=synk_schedule_merge_table_name();
    $conn->query('INSERT INTO '.$mergeTable.' (owner_offering_id,member_offering_id,merge_scope) VALUES ('.(int)$f['offerings'][0]['offering_id'].','.(int)$f['offerings'][1]['offering_id'].",'FULL')");
    $merged=synk_assessment_missing_submissions_lms($conn,$lms,$context,$id);
    $check($merged['counts']['students']===4&&$merged['counts']['missing']===4&&count(array_unique(array_column($merged['students'],'student_number')))===4,'Merged classes combine both rosters and deduplicate students enrolled in both.');
    $conn->query('ROLLBACK TO SAVEPOINT followup_merge');
    $check(array_unique(array_column($report['students'],'status'))===['not_started'],'Students with no attempt are not started, not overdue.');
    $check(strpos($report['notice'],'has not passed')!==false,'A future deadline must not accuse students of missing a passed deadline.');
    $check(strpos($report['message'],'Grading period: Final')!==false&&strpos($report['message'],'Assessment: Quiz <script>literal</script> Second line')!==false,'The complete reminder includes the assessment and correct LMS period, with titles on one line.');
    $check(strpos($report['message'],'PHT')!==false&&strpos($report['message'],'As of:')!==false,'Reminders include an explicit Philippine timestamp and deadline.');
    foreach($report['students'] as $student)$check(strpos($report['message'],$student['student_number'])===false&&strpos($report['message'],$student['student_name'].' — ')!==false,'Copy includes every name and excludes student numbers.');
    $check(strpos(json_encode($report),'answer_key')===false&&!isset($report['assessment']['questions'],$report['students'][0]['answers'],$report['students'][0]['email_address']),'Reports contain no answer keys, answers, grades or emails.');
    $numbers=synk_assessment_query_lms($conn,'SELECT student_id,student_number FROM tbl_student_management WHERE student_id IN (?,?)','ii',[$sid,$second]);$numbers=array_column($numbers,'student_number','student_id');
    $start=synk_student_assessment_action_lms($conn,$lms,$sid,'start',['assessment_id'=>$id]);
    $report=synk_assessment_missing_submissions_lms($conn,$lms,$context,$id);$students=array_column($report['students'],null,'student_number');
    $check($students[$numbers[$sid]]['status']==='in_progress'&&$students[$numbers[$sid]]['deadline_at']===$start['attempt']['deadline_at'],'In-progress attempts stay on the list with their earlier timer deadline.');
    $q=$start['assessment']['questions'][0]['question_id'];
    synk_student_assessment_action_lms($conn,$lms,$sid,'submit',['assessment_id'=>$id,'version'=>1,'answers'=>[$q=>true]]);
    $report=synk_assessment_missing_submissions_lms($conn,$lms,$context,$id);$students=array_column($report['students'],null,'student_number');
    $check($report['counts']===['students'=>3,'submitted'=>1,'missing'=>2]&&!isset($students[$numbers[$sid]]),'Submitted students disappear from the report and reminder counts.');
    $lms->query('SAVEPOINT past_followup');
    synk_assessment_query_lms($lms,"UPDATE tbl_lms_assessments SET due_at='2000-01-01 00:00:00' WHERE assessment_id=?",'i',[$id]);
    $past=synk_assessment_missing_submissions_lms($conn,$lms,$context,$id);
    $check(array_unique(array_column($past['students'],'status'))===['overdue'],'Only a passed deadline marks never-started students overdue.');
    $lms->query('ROLLBACK TO SAVEPOINT past_followup');
    synk_student_assessment_action_lms($conn,$lms,$second,'start',['assessment_id'=>$id]);
    synk_assessment_query_lms($lms,"UPDATE tbl_lms_assessment_attempts SET deadline_at='2000-01-01 00:00:00' WHERE assessment_id=? AND student_id=?",'ii',[$id,$second]);
    $beforeRead=$lms->query('CHECKSUM TABLE '.$lmsTables)->fetch_all(MYSQLI_ASSOC);
    $report=synk_assessment_missing_submissions_lms($conn,$lms,$context,$id);$students=array_column($report['students'],null,'student_number');
    $check($students[$numbers[$second]]['status']==='expired'&&$students[$numbers[$second]]['status_label']==='Attempt ended','Elapsed attempts are outstanding, even if their stored status is still in progress.');
    $check($lms->query('CHECKSUM TABLE '.$lmsTables)->fetch_all(MYSQLI_ASSOC)===$beforeRead,'Reading a follow-up never expires, submits or modifies an attempt.');
    $updated=synk_assessment_schedule_lms($lms,$context,['assessment_id'=>$id,'version'=>1,'opens_at'=>'2098-12-01T08:00','due_at'=>'2099-02-01T17:00'],$actor);
    $report=synk_assessment_missing_submissions_lms($conn,$lms,$context,$id);$students=array_column($report['students'],null,'student_number');
    $check($students[$numbers[$second]]['deadline_at']==='2000-01-01 00:00:00'&&strpos($report['notice'],'not opened yet')!==false,'Schedule edits keep original attempt deadlines and explain that new students cannot start yet.');
    $check(strpos($report['message'],'individual deadline: Jan 1, 2000 at 12:00 AM PHT')!==false,'The copied reminder identifies a differing original attempt deadline rather than implying the new schedule applies to everyone.');
    $denied(static function()use($conn,$lms,$context,$id){$other=$context;$other['portal']['faculty_id']++;synk_assessment_missing_submissions_lms($conn,$lms,$other,$id);},404);
    $denied(static function()use($conn,$lms,$context,$id){$other=$context;$other['class']['offering_id']++;synk_assessment_missing_submissions_lms($conn,$lms,$other,$id);},404);
    synk_assessment_close_lms($lms,$context,['assessment_id'=>$id,'version'=>$updated['version']],$actor);
    $report=synk_assessment_missing_submissions_lms($conn,$lms,$context,$id);
    $check($report['counts']['missing']===2&&in_array('closed',array_column($report['students'],'status'),true),'Closing retains missing names and distinguishes students who never submitted.');
    $assignment=synk_assessment_publish_lms($lms,$context,['grading_period'=>'midterm','assessment_type'=>'assignment','title'=>'Written work','instructions'=>'Respond','total_points'=>10],$actor);
    $report=synk_assessment_missing_submissions_lms($conn,$lms,$context,$assignment['assessment_id']);
    $check($report['due_label']==='No due date'&&strpos($report['notice'],'not necessarily overdue')!==false&&$report['counts']['missing']===3,'Undated written assignments use the same roster without inventing deadlines.');
    foreach([$sid,$second,$third] as $studentId){synk_student_assessment_action_lms($conn,$lms,$studentId,'start',['assessment_id'=>$assignment['assessment_id']]);synk_student_assessment_action_lms($conn,$lms,$studentId,'submit',['assessment_id'=>$assignment['assessment_id'],'version'=>1,'answers'=>['assignment_response'=>'Done']]);}
    $report=synk_assessment_missing_submissions_lms($conn,$lms,$context,$assignment['assessment_id']);
    $check($report['counts']===['students'=>3,'submitted'=>3,'missing'=>0]&&$report['students']===[]&&$report['message']==='','Submitted written work awaiting grading is complete and produces no reminder.');
    synk_assessment_query_lms($conn,'UPDATE tbl_student_management_enrolled_subjects SET is_active=0 WHERE faculty_id=?','i',[$f['faculty_id']]);
    $report=synk_assessment_missing_submissions_lms($conn,$lms,$context,$id);
    $check($report['counts']===['students'=>0,'submitted'=>0,'missing'=>0]&&$report['message']==='','Withdrawn and historical attempts cannot create missing students in an empty roster.');
} finally {$lms->rollback();$conn->rollback();}
$check($conn->query('CHECKSUM TABLE '.$coreTables)->fetch_all(MYSQLI_ASSOC)===$coreBefore,'Core academic and enrollment fixtures must roll back.');
$check($lms->query('CHECKSUM TABLE '.$lmsTables)->fetch_all(MYSQLI_ASSOC)===$lmsBefore,'LMS fixtures must roll back.');
echo 'LMS assessment follow-up: ',$checks,' checks passed. All fixtures rolled back.',PHP_EOL;
